  3: { de: "Erfahren Sie mehr \u00fcber das Bildungssystem der aserbaidschanischen Sprache.", fr: "Apprenez le syst\u00e8me d\u2019enseignement en langue az\u00e9rie\u00e7anne.", zh: "\u4e86\u89e3\u963f\u585e\u62dc\u7586\u8bed\u8a00\u6559\u80b2\u4f53\u7cfb\u3002", ar: "\u062a\u0639\u0631\u0641 \u0639\u0644\u0649 \u0646\u0638\u0627\u0645 \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0628\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0623\u0630\u0631\u0628\u0627\u064a\u062c\u0627\u0646\u064a\u0629.", fa: "\u062f\u0631 \u0628\u0627\u0631\u0647 \u0633\u06cc\u0633\u062a\u0645 \u062a\u0639\u0644\u06cc\u0645 \u0622\u0630\u0631\u0628\u0627\u06cc\u062c\u0627\u0646\u06cc \u0627\u0637\u0644\u0627\u0639 \u06a9\u0646\u06cc\u062f.", tk: "Azerba\u00fdjan dilinde e\u011fitim sistemi hakynda \u00f6\u011freni\u0148.", kk: "Azerbayjan t\u00f6l\u00edndeg\u00ed bilim j\u00fcy\u00e9sin \u0430\u0448\u044b\u04a3\u044b\u0437.", ky: "Azerbayjan tilindegi bilim sistemi тууралуу \u0431\u0438\u043b\u0438\u043d\u0438\u0437.", bg: "\u041d\u0430\u0443\u0447\u0435\u0442\u0435 \u0437\u0430 \u0441\u0438\u0441\u0442\u0435\u043c\u0430\u0442\u0430 \u043d\u0430 \u043e\u0431\u0440\u0430\u0437\u043e\u0432\u0430\u043d\u0438\u0435 \u043d\u0430 \u0430\u0437\u0435\u0440\u0431\u0430\u0439\u0434\u0436\u0430\u043d\u0441\u043a\u0438 \u0435\u0437\u0438\u043a.", ur: "\u0622\u0630\u0631\u0628\u0627\u0626\u06cc\u062c\u0627\u0646\u06cc \u0632\u0628\u0627\u0646 \u0645\u06cc\u06ba \u062a\u0639\u0644\u06cc\u0645 \u0633\u0633\u0679\u0645 \u06a9\u0645 \u06a9\u0631\u06cc\u06ba.", uz: "Ozarbayjon tilida ta'lim tizimi haqida bilib oling.", sw: "Jifunze kuhusu mfumo wa elimu kwa lugha ya Azerbaijan.", so: "Wax ka baro nidaamka waxbarashada Afafka Azerbaijan.", id: "Pelajari sistem pendidikan bahasa Azerbaijan." },
